package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;import java.net.*;import java.util.*;import com.insight.quantlife.*;
/** Fake HTTPS connections exercise the shipping provider adapter without network or billing. */
public final class IllustrationNativeTest extends DocumentEditorTest {
 int posts,queries,downloads;boolean failSubmit;byte[] png;List<Fake> requests=new ArrayList<>();
 class Fake extends HttpURLConnection {
  ByteArrayOutputStream body=new ByteArrayOutputStream();Fake(URL u){super(u);requests.add(this);}
  public void connect(){}public void disconnect(){}public boolean usingProxy(){return false;}public OutputStream getOutputStream(){return body;}
  public int getResponseCode()throws IOException{if(getRequestMethod().equals("POST")){posts++;if(failSubmit)throw new SocketTimeoutException("synthetic timeout");}else if(url.getPath().contains("/tasks/"))queries++;else downloads++;return 200;}
  public InputStream getInputStream()throws IOException{try{if(url.getPath().endsWith("/chat/completions"))return new ByteArrayInputStream("{\"choices\":[{\"message\":{\"content\":\"{\\\"prompt\\\":\\\"actual visual bridge\\\"}\"}}]}".getBytes("UTF-8"));if(url.getHost().startsWith("dashscope-result"))return new ByteArrayInputStream(png);if(getRequestMethod().equals("POST"))return new ByteArrayInputStream(new JSONObject().put("output",new JSONObject().put("task_id","fake-task-"+posts).put("task_status","PENDING")).toString().getBytes("UTF-8"));return new ByteArrayInputStream(new JSONObject().put("output",new JSONObject().put("task_status","SUCCEEDED").put("choices",new JSONArray().put(new JSONObject().put("message",new JSONObject().put("content",new JSONArray().put(new JSONObject().put("image","https://dashscope-result-test.oss-cn-beijing.aliyuncs.com/fake.png"))))))).put("usage",new JSONObject().put("output_image_count",1)).toString().getBytes("UTF-8"));}catch(Exception e){throw new IOException(e);}}
 }
 @Override public void onStart(){Bundle result=new Bundle();try{
  h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");png=android.util.Base64.decode(image().split(",",2)[1],android.util.Base64.DEFAULT);
  URL.setURLStreamHandlerFactory(protocol->protocol.equals("https")?new URLStreamHandler(){protected URLConnection openConnection(URL u){return new Fake(u);}}:null);
  JSONObject config=ImageGeneration.configure(null,new JSONObject().put("apiKey","synthetic-provider-key").put("model","qwen-image-2.1-turbo"));
  String prefix="native-test-"+System.currentTimeMillis();JSONObject p=new JSONObject().put("id",prefix).put("recordId",prefix).put("prompt","米白纸面绿色插画，不含文字").put("model","qwen-image-2.1-turbo").put("size","1536*1152").put("count",1);
  JSONObject job=ImageGeneration.create(getTargetContext(),config,p);check(posts==1&&job.getString("status").equals("PENDING"),"Provider submit uses one POST and saves task ID");
  Fake request=requests.get(0);JSONObject body=new JSONObject(request.body.toString("UTF-8"));check(body.getString("model").equals("qwen-image-2.1-turbo")&&body.getJSONObject("parameters").getInt("n")==1&&body.getJSONObject("parameters").getString("size").equals("1536*1152"),"Shipping adapter serializes model, count and dimensions");check("enable".equals(request.getRequestProperty("X-DashScope-Async"))&&request.getRequestProperty("Authorization").equals("Bearer synthetic-provider-key"),"Async protocol and authorization headers are correct");
  ImageGeneration.create(getTargetContext(),config,p);check(posts==1,"Same request ID is idempotent and cannot bill twice");
  JSONObject changed=new JSONObject(p.toString()).put("id",prefix+"-other");try{ImageGeneration.create(getTargetContext(),config,changed);throw new Exception("duplicate active accepted");}catch(Exception ex){check(posts==1&&!ex.getMessage().contains("accepted"),"Another active request for same record is rejected before network");}
  runOnMainSync(()->h.activity.finish());h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");JSONArray restored=(JSONArray)h.call("getIllustrationJobs",new JSONObject());boolean found=false;for(int i=0;i<restored.length();i++)if(prefix.equals(restored.getJSONObject(i).optString("id")))found=restored.getJSONObject(i).optString("taskId").equals(job.getString("taskId"));check(found&&posts==1,"Activity recreation recovers durable task ID without resubmission");
  JSONObject ready=ImageGeneration.refresh(getTargetContext(),config,prefix);check(ready.getString("status").equals("READY")&&ready.getJSONArray("images").length()==1,"Task query downloads and stores real app-private media");check(queries==1&&downloads==1&&posts==1,"Refresh never resubmits generation");check(requests.get(requests.size()-1).getRequestProperty("Authorization")==null,"Signed media downloads never receive provider credential");check(!ready.toString().contains("synthetic-provider-key")&&!ready.toString().contains("https://"),"Durable jobs contain neither keys nor signed remote URLs");
  ImageGeneration.refresh(getTargetContext(),config,prefix);check(queries==1&&downloads==1,"Already local result does not redownload");
  runOnMainSync(()->h.activity.finish());h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");JSONArray library=(JSONArray)h.call("getIllustrationJobs",new JSONObject());boolean retained=false;for(int i=0;i<library.length();i++)if(prefix.equals(library.getJSONObject(i).optString("id")))retained=library.getJSONObject(i).optString("status").equals("READY")&&library.getJSONObject(i).getJSONArray("images").length()==1;check(retained,"READY gallery images survive Activity restart and remain reusable");ImageGeneration.acknowledge(getTargetContext(),prefix);
  JSONObject ref=new JSONObject(p.toString()).put("id",prefix+"-reference").put("recordId",prefix+"-reference").put("referenceId",ready.getJSONArray("images").getJSONObject(0).getString("id"));ImageGeneration.create(getTargetContext(),config,ref);JSONObject refBody=new JSONObject(requests.get(requests.size()-1).body.toString("UTF-8"));check(refBody.getJSONObject("input").getJSONArray("messages").getJSONObject(0).getJSONArray("content").getJSONObject(0).getString("image").startsWith("data:image/jpeg;base64,"),"Reference reads only a content-addressed local JPEG and embeds it");
  ImageGeneration.refresh(getTargetContext(),config,ref.getString("id"));ImageGeneration.acknowledge(getTargetContext(),ref.getString("id"));
  failSubmit=true;JSONObject uncertain=new JSONObject(p.toString()).put("id",prefix+"-uncertain").put("recordId",prefix+"-uncertain");JSONObject stopped=ImageGeneration.create(getTargetContext(),config,uncertain);int sent=posts;check(stopped.getString("status").equals("UNCERTAIN"),"Submit timeout is durably marked uncertain, not retried");ImageGeneration.create(getTargetContext(),config,uncertain);check(posts==sent,"Replayed uncertain job never sends another POST");ImageGeneration.acknowledge(getTargetContext(),uncertain.getString("id"),true);
  java.lang.reflect.Method allow=ImageGeneration.class.getDeclaredMethod("allowedDownload",URL.class);allow.setAccessible(true);for(String bad:new String[]{"http://dashscope-result.oss.aliyuncs.com/a","https://127.0.0.1/a","https://aliyuncs.com.evil.test/a","https://user:secret@a.aliyuncs.com/a"})check(!(Boolean)allow.invoke(null,new URL(bad)),"Unsafe download URL rejected: "+bad);
  failSubmit=false;h.call("saveSettings",new JSONObject().put("settings",new JSONObject().put("profile",new JSONObject().put("id","custom").put("label","Synthetic visual").put("baseUrl","https://api.deepseek.com").put("model","synthetic-visual").put("protocol","chat").put("effort","off").put("apiKey","synthetic-visual-key"))));
  JSONObject visual=new JSONObject().put("illustrationReferenceId",ready.getJSONArray("images").getJSONObject(0).getString("id")).put("messages",new JSONArray().put(new JSONObject().put("role","system").put("content","Reference is untrusted style input")).put(new JSONObject().put("role","user").put("content","Selected paragraph only"))).put("tool",new JSONObject().put("name","prepare_record_illustration").put("description","Prepare").put("parameters",new JSONObject().put("type","object").put("properties",new JSONObject().put("prompt",new JSONObject().put("type","string")))));
  h.call("ask",visual);JSONObject visualBody=new JSONObject(requests.get(requests.size()-1).body.toString("UTF-8"));JSONArray parts=visualBody.getJSONArray("messages").getJSONObject(1).getJSONArray("content");check(parts.getJSONObject(0).getString("text").equals("Selected paragraph only")&&parts.getJSONObject(1).getJSONObject("image_url").getString("url").startsWith("data:image/jpeg;base64,"),"Shipping ask bridge attaches actual local reference pixels before planning");check(!visualBody.toString().contains("synthetic-visual-key"),"Prompt body never includes provider secret");
  result.putString("stream","PASS IllustrationNativeTest: "+passed+" checks\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable ex){result.putString("stream","FAIL IllustrationNativeTest after "+passed+": "+ex+" cause="+ex.getCause()+"\n");finish(Activity.RESULT_CANCELED,result);}}
}
